        if t in UNSTATED or IDENTITY.fullmatch(t) or t.startswith(("amt", "beyond")) or t.endswith("_retrial"):
            continue
        if t in labels:
            out.append(labels[t])
        elif t in PHRASES:
            out.append(PHRASES[t].format(claimant=claimant))
        elif t.startswith("judgment_"):
